SELECT 'create_deepagent', 'Create DeepAgent', 'Create a new DeepAgent in the database. The agent will immediately appear in the DeepAgent Studio.

Use this tool when the user wants to SAVE a designed agent configuration permanently.

Args:
    name: Agent name (e.g. ''市场研究助手'')
    system_prompt: The COMPLETE system prompt defining the agent''s behavior
    native_tools: List of tool names the agent should have (e.g. [''web_search'', ''web_fetch'', ''reasoning_chain''])
    skills: List of skill IDs (e.g. [''web-search'', ''text-summarizer''])
    description: Short 1-2 sentence description of what the agent does
    category: Agent category (e.g. ''Research'', ''Coding'', ''Custom'')
    model: Model name (default: ''minimax-m3'')
    temperature: Model temperature 0.0-1.0 (default: 0.7)', 'python_function', 'custom', '{"function_name": "create_deepagent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef create_deepagent(name: str,\n                     system_prompt: str,\n                     native_tools: list[str],\n                     skills: list[str] | None = None,\n                     description: str | None = None,\n                     category: str | None = None,\n                     model: str | None = None,\n                     temperature: float | None = None) -> str:\n    \"\"\"Create a new DeepAgent in the database. The agent will immediately appear in the DeepAgent Studio.\n\n    Use this tool when the user wants to SAVE a designed agent configuration permanently.\n\n    Args:\n        name: Agent name (e.g. ''市场研究助手'')\n        system_prompt: The COMPLETE system prompt defining the agent''s behavior\n        native_tools: List of tool names the agent should have (e.g. [''web_search'', ''web_fetch'', ''reasoning_chain''])\n        skills: List of skill IDs (e.g. [''web-search'', ''text-summarizer''])\n        description: Short 1-2 sentence description of what the agent does\n        category: Agent category (e.g. ''Research'', ''Coding'', ''Custom'')\n        model: Model name (default: ''minimax-m3'')\n        temperature: Model temperature 0.0-1.0 (default: 0.7)\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import (\n        DeepAgentTemplate,\n        DeepAgentConfig,\n        create_default_middleware_config,\n        create_default_backend_config,\n        create_default_guardrails_config,\n    )\n    import json\n\n    db = SessionLocal()\n    try:\n        cfg = DeepAgentConfig(\n            model=model or \"minimax-m3\",\n            system_prompt=system_prompt.strip(),\n            native_tools=native_tools or [],\n            skills=skills or [],\n            tools=[],\n            cli_tools=[],\n            custom_tools=[],\n            temperature=temperature if temperature is not None else 0.7,\n            use_deepagents=True,\n            middleware=create_default_middleware_config(),\n            subagents=[],\n            backend=create_default_backend_config(),\n            guardrails=create_default_guardrails_config(),\n        )\n\n        agent = DeepAgentTemplate(\n            name=name.strip(),\n            description=(description or \"\").strip(),\n            category=category or \"Custom\",\n            config=cfg.dict(),\n            middleware_config=[m.dict() for m in cfg.middleware],\n            subagents_config=[],\n            backend_config=cfg.backend.dict(),\n            guardrails_config=cfg.guardrails.dict(),\n        )\n\n        db.add(agent)\n        db.commit()\n        db.refresh(agent)\n\n        return (\n            f\"✅ Agent ''{name}'' (id={agent.id}) created successfully!\\n\\n\"\n            f\"Agent is now available in the DeepAgent Studio. The user can:\\n\"\n            f\"1. Select it from the agent dropdown to see its topology\\n\"\n            f\"2. Click ''Test'' to start a conversation with it\\n\"\n            f\"3. Click ''Edit'' to modify its configuration\"\n        )\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to create agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "string", "description": ""}, "skills": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "category": {"type": "string", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "string", "description": ""}, "skills": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "category": {"type": "string", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}}, "required": ["name", "system_prompt", "native_tools"]}', 'string', NULL, '{"category": "agents", "order": 27, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-08-01 14:44:18.034592+00:00', '2026-10-13 09:07:27.335163+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'create_deepagent');

