SELECT 'doc_index_pages', 'Doc Index - Get Page Content', 'Get the full content of specific pages from a document. Specify pages as ranges like ''5-7'', specific pages like ''3,8'', or a single page like ''12''.', 'python_function', 'custom', '{"function_name": "doc_index_pages", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nimport os\n\n_DOC_INDEX_BASE = None\n\ndef _get_doc_index_base() -> str:\n    \"\"\"Get the doc_index workspace base path.\"\"\"\n    global _DOC_INDEX_BASE\n    if _DOC_INDEX_BASE is None:\n        try:\n            # Follow the env-configurable workspace root (WORKSPACE_BASE_DIR).\n            from services.workspace_manager import get_workspace_manager\n            default_base = str(get_workspace_manager().base_dir / \"default\")\n        except Exception:\n            default_base = os.path.join(\n                os.path.dirname(os.path.dirname(__file__)), \"outputs\", \"default\"\n            )\n        _DOC_INDEX_BASE = os.environ.get(\"DOC_INDEX_BASE\", default_base)\n    return _DOC_INDEX_BASE\n\ndef _get_doc_client():\n    \"\"\"Get a DocIndexClient for the current workspace.\"\"\"\n    from services.doc_index_service import DocIndexClient\n    return DocIndexClient(_get_doc_index_base())\n\ndef doc_index_pages(doc_id: str, pages: str, workspace: Optional[str] = None) -> str:\n    \"\"\"\n    Get the full content of specific pages from a document.\n\n    Args:\n        doc_id: The document ID (from doc_index_list)\n        pages: Page numbers to retrieve. Examples: ''5-7'' (range), ''3,8'' (specific), ''12'' (single).\n               Use ''1-3'' to read the first few pages (often contains the table of contents).\n        workspace: Optional override for the doc_index workspace path\n    \"\"\"\n    try:\n        if workspace:\n            from services.doc_index_service import DocIndexClient\n            client = DocIndexClient(workspace)\n        else:\n            client = _get_doc_client()\n\n        doc_meta = client.get_document(doc_id)\n        if \"error\" in doc_meta:\n            return doc_meta[\"error\"]\n\n        content_list = client.get_page_content(doc_id, pages)\n        if not content_list:\n            return f\"No content found for pages: {pages}\"\n\n        result = [f\"## Content: {doc_meta.get(''doc_name'', ''Document'')} (pages {pages})\", \"\"]\n        for entry in content_list:\n            page_num = entry.get(\"page\", \"?\")\n            text = entry.get(\"content\", \"\")\n            result.append(f\"--- Page {page_num} ---\")\n            result.append(text)\n            result.append(\"\")\n\n        return \"\\n\".join(result)\n    except Exception as e:\n        return f\"Error getting page content: {e}\"", "args_schema": {"doc_id": {"type": "string", "description": ""}, "pages": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"doc_id": {"type": "string", "description": ""}, "pages": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}, "required": ["doc_id", "pages"]}', 'string', NULL, '{"category": "graph", "order": 46, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034583+00:00', '2026-10-13 09:07:27.335159+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'doc_index_pages');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'doc_index_structure', 'Doc Index - Get Document Structure', 'Get the table-of-contents tree structure for a document (headings with page numbers, no body text). Use this to navigate before reading pages.', 'python_function', 'custom', '{"function_name": "doc_index_structure", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nimport os\n\n_DOC_INDEX_BASE = None\n\ndef _get_doc_index_base() -> str:\n    \"\"\"Get the doc_index workspace base path.\"\"\"\n    global _DOC_INDEX_BASE\n    if _DOC_INDEX_BASE is None:\n        try:\n            # Follow the env-configurable workspace root (WORKSPACE_BASE_DIR).\n            from services.workspace_manager import get_workspace_manager\n            default_base = str(get_workspace_manager().base_dir / \"default\")\n        except Exception:\n            default_base = os.path.join(\n                os.path.dirname(os.path.dirname(__file__)), \"outputs\", \"default\"\n            )\n        _DOC_INDEX_BASE = os.environ.get(\"DOC_INDEX_BASE\", default_base)\n    return _DOC_INDEX_BASE\n\ndef _get_doc_client():\n    \"\"\"Get a DocIndexClient for the current workspace.\"\"\"\n    from services.doc_index_service import DocIndexClient\n    return DocIndexClient(_get_doc_index_base())\n\ndef doc_index_structure(doc_id: str, workspace: Optional[str] = None) -> str:\n    \"\"\"\n    Get the table-of-contents tree structure for a document.\n\n    Returns the document''s heading hierarchy with page numbers (no body text).\n    Use this to navigate to the right section before reading page content.\n\n    Args:\n        doc_id: The document ID (from doc_index_list)\n        workspace: Optional override for the doc_index workspace path\n    \"\"\"\n    try:\n        if workspace:\n            from services.doc_index_service import DocIndexClient\n            client = DocIndexClient(workspace)\n        else:\n            client = _get_doc_client()\n\n        doc_meta = client.get_document(doc_id)\n        if \"error\" in doc_meta:\n            return doc_meta[\"error\"]\n\n        structure = client.get_document_structure(doc_id)\n        if not structure:\n            return f\"Document ''{doc_meta.get(''doc_name'', doc_id)}'' has no TOC structure. Use doc_index_pages to read content directly.\"\n\n        def _format_tree(nodes, indent=0):\n            lines = []\n            for n in nodes:\n                title = n.get(\"title\", \"\")\n                page = n.get(\"page\", n.get(\"line\", \"\"))\n                prefix = \"  \" * indent + \"- \"\n                page_str = f\" (p.{page})\" if page else \"\"\n                lines.append(f\"{prefix}**{title}**{page_str}\")\n                children = n.get(\"children\", [])\n                if children:\n                    lines.extend(_format_tree(children, indent + 1))\n            return lines\n\n        result = [f\"## Structure: {doc_meta.get(''doc_name'', ''Document'')}\"]\n        result.extend(_format_tree(structure))\n        return \"\\n\".join(result)\n\n    except Exception as e:\n        return f\"Error getting document structure: {e}\"", "args_schema": {"doc_id": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"doc_id": {"type": "string", "description": ""}, "workspace": {"type": "string", "description": "", "default": null}}, "required": ["doc_id"]}', 'string', NULL, '{"category": "graph", "order": 45, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034581+00:00', '2026-10-13 09:07:27.335159+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'doc_index_structure');

