SELECT 'doc_to_deck', 'Document to Deck (HTML+PPTX)', 'Convert one or more documents (.md / .txt / .pdf / .docx) into themed
HTML + PPTX decks in a single call (batch supported).

Pipeline: read each document → LLM outline (12–15 slides, draft → refine)
→ normalize against the template → render HTML (single file, no CDN) and
PPTX (from the template''s own layouts). With multiple documents, each doc
becomes a section of one combined deck.

Args:
    file_paths: JSON array of absolute document paths, e.g.
        ''["/abs/doc1.md", "/abs/doc2.pdf"]'' (a single path is fine too).
    template: Template id (business|fashion|tech|health|education|minimal).
    formats: Comma-separated outputs: html, pptx (pdf also supported).
    output_dir: Output directory (inside the presentation output folder).
    pages: Target slide count (0 = template default).

Returns:
    Paths of the generated files.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import doc_to_deck\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"Convert one or more documents (.md / .txt / .pdf / .docx) into themed HTML + PPTX decks in a single call (batch supported).  Pipeline: read each document → LLM \"\"\"\n    return str(await doc_to_deck.ainvoke({**kwargs}))\n", "args_schema": {"file_paths": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "formats": {"type": "string", "description": "", "default": "html,pptx"}, "output_dir": {"type": "string", "description": "", "default": ""}, "pages": {"type": "integer", "description": "", "default": 0}}}', '{"type": "object", "properties": {"file_paths": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "formats": {"type": "string", "description": "", "default": "html,pptx"}, "output_dir": {"type": "string", "description": "", "default": ""}, "pages": {"type": "integer", "description": "", "default": 0}}, "required": ["file_paths"]}', 'string', NULL, '{"category": "presentation", "order": 21, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078099+00:00', '2026-10-13 09:07:27.335196+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'doc_to_deck');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'doc_to_slides_outline', 'Document to Slides Outline', 'Turn a document (.md / .txt / .pdf / .docx) into a validated slides outline.

Reads the document server-side, then runs two LLM passes (draft → refine)
producing a 12–15 slide outline JSON. The outline is normalized against the
selected template''s constraints (page clamp, bullet caps, auto-highlight of
key numbers). Feed the returned JSON into gen_html_deck / gen_pptx, or use
doc_to_deck to render both formats in one call.

Args:
    file_path: Absolute path of the source document.
    template: Template id (business|fashion|tech|health|education|minimal).
    pages: Target slide count (0 = template default, 12–15).

Returns:
    The normalized outline as a JSON string.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import doc_to_slides_outline\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"Turn a document (.md / .txt / .pdf / .docx) into a validated slides outline.  Reads the document server-side, then runs two LLM passes (draft → refine) producin\"\"\"\n    return str(await doc_to_slides_outline.ainvoke({**kwargs}))\n", "args_schema": {"file_path": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "pages": {"type": "integer", "description": "", "default": 0}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}, "template": {"type": "string", "description": "", "default": "business"}, "pages": {"type": "integer", "description": "", "default": 0}}, "required": ["file_path"]}', 'string', NULL, '{"category": "presentation", "order": 20, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078097+00:00', '2026-10-13 09:07:27.335196+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'doc_to_slides_outline');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'edit_file', 'Edit File', 'Perform exact string replacement in a file.

Finds the old_string in the file and replaces it with new_string.
The old_string must be unique in the file to avoid ambiguous edits.

Example:
    edit_file(file_path="config.py", old_string="DEBUG = False", new_string="DEBUG = True")', 'python_function', 'custom', '{"function_name": "_edit_file_impl", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nimport os\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services.workspace_manager import get_workspace_manager\n    roots = [\n        get_workspace_manager().base_dir,   # backend/outputs (write_file home)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef _record_file_version(\n    file_path: Path,\n    operation: str,\n    content: str = None,\n    old_string: str = None,\n    new_string: str = None,\n    workspace_context: dict = None,\n    agent_context: dict = None\n) -> None:\n    \"\"\"\n    Record a file version in the database for diff viewing.\n\n    This creates a FileVersion record that tracks changes to files,\n    enabling version history and diff viewing in the UI.\n\n    Args:\n        file_path: Full path to the file\n        operation: \"create\", \"edit\", or \"replace\"\n        content: Full content for create/replace operations\n        old_string: For edit operations, the string that was replaced\n        new_string: For edit operations, the replacement string\n        workspace_context: Context about the workspace (project_id, workflow_id, task_id)\n        agent_context: Context about the agent making the change\n    \"\"\"\n    try:\n        import hashlib\n        from db.database import SessionLocal\n        from models.workspace_file import WorkspaceFile\n        from models.file_version import FileVersion\n        from services.workspace_manager import get_workspace_manager\n\n        # Compute relative path from outputs/ directory\n        workspace_mgr = get_workspace_manager()\n        outputs_dir = workspace_mgr.base_dir\n        try:\n            relative_path = str(file_path.relative_to(outputs_dir))\n        except ValueError:\n            relative_path = str(file_path)\n\n        db = SessionLocal()\n        try:\n            # Find or create the WorkspaceFile record\n            workspace_file = db.query(WorkspaceFile).filter(\n                WorkspaceFile.file_path == relative_path\n            ).first()\n\n            if not workspace_file:\n                logger.debug(f\"No WorkspaceFile record found for {relative_path}, skipping version tracking\")\n                return\n\n            # Get the current version number\n            max_version = db.query(FileVersion).filter(\n                FileVersion.workspace_file_id == workspace_file.id\n            ).count()\n            new_version_number = max_version + 1\n\n            # Compute content hash if we have content\n            content_hash = None\n            if content:\n                content_hash = hashlib.sha256(content.encode(''utf-8'')).hexdigest()\n\n            # Calculate line changes for edits\n            lines_added = None\n            lines_removed = None\n            change_summary = None\n\n            if operation == \"create\":\n                lines_added = content.count(''\\n'') + 1 if content else 0\n                lines_removed = 0\n                change_summary = f\"Created file with {lines_added} lines\"\n            elif operation == \"edit\" and old_string and new_string:\n                old_lines = old_string.count(''\\n'')\n                new_lines = new_string.count(''\\n'')\n                lines_added = max(0, new_lines - old_lines)\n                lines_removed = max(0, old_lines - new_lines)\n                change_summary = f\"Replaced {len(old_string)} chars with {len(new_string)} chars\"\n            elif operation == \"replace\":\n                lines_added = content.count(''\\n'') + 1 if content else 0\n                change_summary = f\"Replaced entire file ({lines_added} lines)\"\n\n            # Create the version record\n            file_version = FileVersion(\n                workspace_file_id=workspace_file.id,\n                version_number=new_version_number,\n                content_hash=content_hash,\n                content_snapshot=content if operation in (\"create\", \"replace\") else None,\n                operation=operation,\n                old_string=old_string,\n                new_string=new_string,\n                agent_label=agent_context.get(''agent_label'') if agent_context else None,\n                agent_type=agent_context.get(''agent_type'') if agent_context else None,\n                node_id=agent_context.get(''node_id'') if agent_context else None,\n                task_id=workspace_context.get(''task_id'') if workspace_context else None,\n                execution_id=workspace_context.get(''execution_id'') if workspace_context else None,\n                change_summary=change_summary,\n                lines_added=lines_added,\n                lines_removed=lines_removed,\n            )\n            db.add(file_version)\n            db.commit()\n\n            logger.debug(f\"Recorded version {new_version_number} for {relative_path} (operation: {operation})\")\n\n        finally:\n            db.close()\n\n    except Exception as e:\n        # Don''t fail the file operation if version recording fails\n        logger.warning(f\"Could not record file version: {e}\")\n\ndef _edit_file_impl(\n    file_path: str,\n    old_string: str,\n    new_string: str,\n    _workspace_context: dict = None,\n    _agent_context: dict = None\n) -> str:\n    \"\"\"\n    Implementation of edit_file tool with version tracking.\n\n    Finds the old_string in the file and replaces it with new_string.\n    The old_string must be unique in the file to avoid ambiguous edits.\n\n    Args:\n        file_path: Path to the file to edit\n        old_string: The exact string to find and replace\n        new_string: The string to replace it with\n        _workspace_context: Context about the workspace (for version tracking)\n        _agent_context: Context about the agent (for version tracking)\n\n    Returns:\n        Success message or error if old_string not found/not unique\n    \"\"\"\n    try:\n        path, err = _resolve_sandbox_path(file_path)\n        if err:\n            return err\n\n        if not path.exists():\n            return f\"Error: File not found: {file_path}\"\n\n        if not path.is_file():\n            return f\"Error: Path is not a file: {file_path}\"\n\n        content = path.read_text(encoding=\"utf-8\")\n\n        # Check if old_string exists and is unique\n        count = content.count(old_string)\n        if count == 0:\n            return f\"Error: String not found in file: ''{old_string[:50]}...''\"\n        if count > 1:\n            return f\"Error: String found {count} times. Must be unique for safe replacement.\"\n\n        # Perform replacement\n        new_content = content.replace(old_string, new_string, 1)\n        path.write_text(new_content, encoding=\"utf-8\")\n\n        # Phase 2: durable storage copy when STORAGE_MODE=db (no-op in local).\n        from services.workspace_manager import get_workspace_manager\n        get_workspace_manager().persist_output(path, new_content.encode(\"utf-8\"))\n\n        logger.info(f\"Edited file: {file_path}\")\n\n        # Record version for diff tracking\n        _record_file_version(\n            file_path=path,\n            operation=\"edit\",\n            content=new_content,  # Store full content after edit\n            old_string=old_string,\n            new_string=new_string,\n            workspace_context=_workspace_context,\n            agent_context=_agent_context\n        )\n\n        return f\"Successfully replaced string in {path.name}\"\n\n    except UnicodeDecodeError:\n        return f\"Error: File is not a text file or uses unsupported encoding\"\n    except Exception as e:\n        logger.error(f\"Error editing file {file_path}: {e}\")\n        return f\"Error editing file: {str(e)}\"", "args_schema": {"file_path": {"type": "string", "description": "Path to the file to edit"}, "old_string": {"type": "string", "description": "The exact string to find and replace (must be unique in file)"}, "new_string": {"type": "string", "description": "The string to replace it with"}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": "Path to the file to edit"}, "old_string": {"type": "string", "description": "The exact string to find and replace (must be unique in file)"}, "new_string": {"type": "string", "description": "The string to replace it with"}}, "required": ["file_path", "old_string", "new_string"]}', 'string', NULL, '{"category": "filesystem", "order": 6, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034569+00:00', '2026-10-13 09:07:27.335149+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'edit_file');

