SELECT 'gen_html_deck', 'Generate HTML Deck', 'Generate a single-file themed HTML slide deck from a slides JSON outline.

Args:
    title: Deck title (used in the HTML <title> and fallback filename).
    slides_json: JSON object with "title" and "slides" (same schema as
        gen_pptx: types title|section|content|data|conclusion|closing|image,
        optional bullets / highlight / speaker_notes).
    output_dir: Optional directory (inside the presentation output folder).
    theme: Named template palette (business|fashion|tech|health|education|minimal).
    filename: Optional explicit filename (must end .html).

Returns:
    Absolute path to the generated .html file.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import gen_html_deck\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"Generate a single-file themed HTML slide deck from a slides JSON outline.  Args:     title: Deck title (used in the HTML <title> and fallback filename).     sli\"\"\"\n    return str(await gen_html_deck.ainvoke({**kwargs}))\n", "args_schema": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}}', '{"type": "object", "properties": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}, "filename": {"type": "string", "description": "", "default": ""}}, "required": ["title", "slides_json"]}', 'string', NULL, '{"category": "presentation", "order": 18, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078089+00:00', '2026-10-13 09:07:27.335194+00:00'
