SELECT 'gen_pptx', 'Generate PPTX', 'Generate a styled PowerPoint (.pptx) deck from a slides JSON outline.

Args:
    title: Deck title shown in the filename and slide footers.
    slides_json: JSON object with "title" and "slides". Each slide has
        "type" (title|section|content|data|conclusion|closing|image),
        "title", optional "subtitle", optional "bullets" (list of
        strings), optional "highlight" (list of substrings rendered as
        big accent numbers), and optional "speaker_notes".
    output_dir: Optional directory (inside the presentation output folder)
        to write the file. Created if it does not exist. Defaults to
        PRESENTATION_OUTPUT_DIR.
    theme: Named template palette — one of business (navy/gold),
        fashion (black/gold serif), tech (slate/cyan), health (teal),
        education (indigo/amber), minimal (monochrome). Default business.

Returns:
    Absolute path to the generated .pptx file.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import gen_pptx\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"Generate a styled PowerPoint (.pptx) deck from a slides JSON outline.  Args:     title: Deck title shown in the filename and slide footers.     slides_json: JSO\"\"\"\n    return str(await gen_pptx.ainvoke({**kwargs}))\n", "args_schema": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}}}', '{"type": "object", "properties": {"title": {"type": "string", "description": ""}, "slides_json": {"type": "string", "description": ""}, "output_dir": {"type": "string", "description": "", "default": ""}, "theme": {"type": "string", "description": "", "default": "business"}}, "required": ["title", "slides_json"]}', 'string', NULL, '{"category": "presentation", "order": 17, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-01 14:44:18.034629+00:00', '2026-10-13 09:07:27.335178+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'gen_pptx');

