SELECT 'image_generation', 'Image Generator', 'Generate images from text descriptions using AI image generation models.', 'image_video', 'custom', '{"provider": "openai", "model": "dall-e-3", "api_key_env": "OPENAI_API_KEY", "endpoint": "https://api.openai.com/v1/images/generations"}', '{"type": "object", "properties": {"prompt": {"type": "string", "description": "Text description of the image to generate"}, "size": {"type": "string", "enum": ["1024x1024", "1792x1024", "1024x1792"], "default": "1024x1024"}, "n": {"type": "integer", "default": 1, "description": "Number of images to generate"}}, "required": ["prompt"]}', 'json', NULL, '{"category": "custom"}', FALSE, FALSE, NULL, FALSE, NULL, 0, NULL, 1, '2026-08-15 09:22:35.400633+00:00', '1.0.0', NULL, NULL, FALSE, NULL, '["image", "generation", "ai", "creative"]', '2026-07-02 16:48:11.049183+00:00', '2026-08-15 09:22:35.400868+00:00'
