SELECT 'list_deck_templates', 'List Deck Templates', 'List the available deck templates (theme + layout sets) with a short
description of each, so the caller can pick one for doc_to_deck / gen_pptx.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import list_deck_templates\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"List the available deck templates (theme + layout sets) with a short description of each, so the caller can pick one for doc_to_deck / gen_pptx.\"\"\"\n    return str(await list_deck_templates.ainvoke({**kwargs}))\n", "args_schema": {}}', '{"type": "object", "properties": {}, "required": []}', 'string', NULL, '{"category": "presentation", "order": 22, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078101+00:00', '2026-10-13 09:07:27.335197+00:00'
