SELECT 'neo4j_delete_doc', 'Neo4j - Delete Document', 'Delete a Document node from Neo4j by project_id and name.

Removes the document from the graph index so it no longer appears
in search results. The actual file on disk is NOT deleted.

Args:
    project_id: Project ID
    name: Document name in Neo4j

Returns:
    Confirmation message

Example:
    >>> neo4j_delete_doc(project_id=1, name="cfd711e3_report.pdf")', 'python_function', 'custom', '{"function_name": "neo4j_delete_doc", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_delete_doc(project_id: int, name: str) -> str:\n    \"\"\"\n    Delete a Document node from Neo4j by project_id and name.\n\n    Removes the document from the graph index so it no longer appears\n    in search results. The actual file on disk is NOT deleted.\n\n    Args:\n        project_id: Project ID\n        name: Document name in Neo4j\n\n    Returns:\n        Confirmation message\n\n    Example:\n        >>> neo4j_delete_doc(project_id=1, name=\"cfd711e3_report.pdf\")\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        deleted = idx.delete_document(project_id, name)\n        if deleted:\n            return f\"✅ Document ''{name}'' deleted from Neo4j (project {project_id}).\"\n        else:\n            return f\"❌ Document ''{name}'' not found in Neo4j (project {project_id}).\"\n    except Exception as e:\n        return f\"❌ Error deleting document: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}, "required": ["project_id", "name"]}', 'string', NULL, '{"category": "graph", "order": 43, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034621+00:00', '2026-10-13 09:07:27.335175+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_delete_doc');

