SELECT 'pg_describe_table', 'PG - Describe Table', 'Show column details for a PostgreSQL table: name, type, nullable, default, constraints.

Use this to understand a table''s schema before querying or inserting data.

Args:
    table_name: Name of the table to describe
    schema_name: Schema name (default: ''public'')

Returns:
    Formatted column list with type, nullable, default, and constraint info

Example:
    >>> pg_describe_table("deep_agent_templates")
    >>> pg_describe_table("skills", schema_name="public")', 'python_function', 'custom', '{"function_name": "pg_describe_table", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_describe_table(table_name: str, schema_name: str = \"public\") -> str:\n    \"\"\"\n    Show column details for a PostgreSQL table: name, type, nullable, default, constraints.\n\n    Use this to understand a table''s schema before querying or inserting data.\n\n    Args:\n        table_name: Name of the table to describe\n        schema_name: Schema name (default: ''public'')\n\n    Returns:\n        Formatted column list with type, nullable, default, and constraint info\n\n    Example:\n        >>> pg_describe_table(\"deep_agent_templates\")\n        >>> pg_describe_table(\"skills\", schema_name=\"public\")\n    \"\"\"\n    import sqlalchemy as sa\n    db = _get_pg_session()\n    try:\n        conn = db.connection()\n        result = conn.execute(sa.text(\n            \"\"\"\n            SELECT\n                c.column_name AS name,\n                c.data_type || COALESCE(''('' || c.character_maximum_length::text || '')'', '''') AS data_type,\n                c.is_nullable,\n                c.column_default AS default_value,\n                CASE WHEN pk.column_name IS NOT NULL THEN ''PRIMARY KEY'' ELSE '''' END AS constraint_type\n            FROM information_schema.columns c\n            LEFT JOIN (\n                SELECT ku.column_name\n                FROM information_schema.table_constraints tc\n                JOIN information_schema.key_column_usage ku\n                    ON tc.constraint_name = ku.constraint_name\n                    AND tc.table_schema = ku.table_schema\n                WHERE tc.constraint_type = ''PRIMARY KEY''\n                    AND tc.table_name = :table_name\n                    AND tc.table_schema = :schema\n            ) pk ON pk.column_name = c.column_name\n            WHERE c.table_name = :table_name AND c.table_schema = :schema\n            ORDER BY c.ordinal_position\n            \"\"\"\n        ), {\"table_name\": table_name, \"schema\": schema_name})\n        rows = result.fetchall()\n        if not rows:\n            return f\"Table ''{schema_name}.{table_name}'' not found.\"\n        lines = [f\"## Columns of ''{schema_name}.{table_name}''\", \"\"]\n        for r in rows:\n            nullable = \"NULL\" if r.is_nullable == \"YES\" else \"NOT NULL\"\n            default = f\" default={r.default_value}\" if r.default_value else \"\"\n            pk = \" 🔑\" if r.constraint_type == \"PRIMARY KEY\" else \"\"\n            lines.append(f\"- **{r.name}**  `{r.data_type}`  {nullable}{default}{pk}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error describing table: {e}\"\n    finally:\n        db.close()", "args_schema": {"table_name": {"type": "string", "description": ""}, "schema_name": {"type": "string", "description": "", "default": "public"}}}', '{"type": "object", "properties": {"table_name": {"type": "string", "description": ""}, "schema_name": {"type": "string", "description": "", "default": "public"}}, "required": ["table_name"]}', 'string', NULL, '{"category": "database", "order": 29, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034596+00:00', '2026-10-13 09:07:27.335165+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_describe_table');

