SELECT 'pg_execute', 'PG - Execute (INSERT/UPDATE/DELETE)', 'Execute a write SQL statement (INSERT, UPDATE, DELETE) against PostgreSQL.

WARNING: This modifies database data. Use with caution.

Args:
    sql: The SQL statement to execute (e.g. "UPDATE deep_agent_templates SET name=''New Name'' WHERE id=1")

Returns:
    Confirmation message with number of rows affected

Example:
    >>> pg_execute("UPDATE deep_agent_templates SET is_public=false WHERE id=1")
    >>> pg_execute("DELETE FROM chat_sessions WHERE is_active=false")', 'python_function', 'custom', '{"function_name": "pg_execute", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_execute(sql: str) -> str:\n    \"\"\"\n    Execute a write SQL statement (INSERT, UPDATE, DELETE) against PostgreSQL.\n\n    WARNING: This modifies database data. Use with caution.\n\n    Args:\n        sql: The SQL statement to execute (e.g. \"UPDATE deep_agent_templates SET name=''New Name'' WHERE id=1\")\n\n    Returns:\n        Confirmation message with number of rows affected\n\n    Example:\n        >>> pg_execute(\"UPDATE deep_agent_templates SET is_public=false WHERE id=1\")\n        >>> pg_execute(\"DELETE FROM chat_sessions WHERE is_active=false\")\n    \"\"\"\n    import sqlalchemy as sa\n    # Write guard: only row-level DML (INSERT/UPDATE/DELETE). Destructive DDL\n    # (CREATE/ALTER/DROP/TRUNCATE) is intentionally excluded, and '';'' is banned\n    # so a stacked \"UPDATE ...; DROP TABLE ...\" can''t slip through.\n    stripped = sql.strip()\n    if stripped.endswith(\";\"):\n        stripped = stripped[:-1].rstrip()\n    if \";\" in stripped:\n        return \"❌ Multiple statements are not allowed. Use a single write statement.\"\n    sql_lower = stripped.lower()\n    if not (sql_lower.startswith(\"insert\")\n            or sql_lower.startswith(\"update\")\n            or sql_lower.startswith(\"delete\")):\n        return (\"❌ Only INSERT/UPDATE/DELETE statements are allowed. \"\n                \"Destructive DDL (CREATE/ALTER/DROP/TRUNCATE) is blocked. \"\n                \"Use pg_query for SELECT.\")\n    sql = stripped\n\n    db = _get_pg_session()\n    try:\n        conn = db.connection()\n        result = conn.execute(sa.text(sql))\n        db.commit()\n        return f\"✅ Statement executed successfully. {result.rowcount} row(s) affected.\"\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Execute error: {e}\"\n    finally:\n        db.close()", "args_schema": {"sql": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"sql": {"type": "string", "description": ""}}, "required": ["sql"]}', 'string', NULL, '{"category": "database", "order": 31, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034600+00:00', '2026-10-13 09:07:27.335167+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_execute');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'pg_get_agent', 'PG - Get Agent Config', 'Get the full configuration of a DeepAgent by its ID.

Returns system prompt, tools, skills, model, temperature, subagents, and middleware config.

Args:
    agent_id: The numeric ID of the agent (use pg_list_agents to find IDs)

Returns:
    Complete agent configuration in a readable format

Example:
    >>> pg_get_agent(agent_id=1)', 'python_function', 'custom', '{"function_name": "pg_get_agent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_get_agent(agent_id: int) -> str:\n    \"\"\"\n    Get the full configuration of a DeepAgent by its ID.\n\n    Returns system prompt, tools, skills, model, temperature, subagents, and middleware config.\n\n    Args:\n        agent_id: The numeric ID of the agent (use pg_list_agents to find IDs)\n\n    Returns:\n        Complete agent configuration in a readable format\n\n    Example:\n        >>> pg_get_agent(agent_id=1)\n    \"\"\"\n    from models.deep_agent import DeepAgentTemplate\n    db = _get_pg_session()\n    try:\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\n        if not agent:\n            return f\"❌ Agent with id={agent_id} not found.\"\n        cfg = agent.config or {}\n        lines = [\n            f\"## Agent: {agent.name} (id={agent.id})\",\n            f\"**Description**: {agent.description or ''(no description)''}\",\n            f\"**Category**: {agent.category}\",\n            f\"**Model**: {cfg.get(''model'', ''not set'')}\",\n            f\"**Temperature**: {cfg.get(''temperature'', 0.7)}\",\n            f\"**Use DeepAgents**: {cfg.get(''use_deepagents'', True)}\",\n            \"\",\n            \"### System Prompt\",\n            \"```\",\n            cfg.get(\"system_prompt\", \"(empty)\")[:2000],\n            \"```\" if len(cfg.get(\"system_prompt\", \"\")) <= 2000 else \"```\\n*...truncated*\",\n            \"\",\n            \"### Tools\",\n            f\"- Native tools: {cfg.get(''native_tools'', [])}\",\n            f\"- Skills: {cfg.get(''skills'', [])}\",\n            f\"- Custom tools: {cfg.get(''custom_tools'', [])}\",\n            \"\",\n            \"### Subagents\",\n        ]\n        subagents = cfg.get(\"subagents\", []) or agent.subagents_config or []\n        if subagents:\n            for s in subagents:\n                name = s.get(\"name\") if isinstance(s, dict) else getattr(s, \"name\", \"?\")\n                desc = s.get(\"description\") if isinstance(s, dict) else getattr(s, \"description\", \"\")\n                lines.append(f\"- **{name}**: {desc}\")\n        else:\n            lines.append(\"(none)\")\n        lines.append(\"\")\n        lines.append(f\"**Version**: {agent.version} | **Public**: {agent.is_public} | **Usage**: {agent.usage_count}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error getting agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"agent_id": {"type": "integer", "description": ""}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "database", "order": 33, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034604+00:00', '2026-10-13 09:07:27.335168+00:00'
