SELECT 'pg_list_agents', 'PG - List Agents', 'List all DeepAgent templates from the database with name, category, and config summary.

Use this to browse available agent configurations before selecting one.

Args:
    category: Optional category filter (e.g. ''Research'', ''Coding'', ''Custom'')

Returns:
    Formatted list of agents with id, name, category, model, and tool count

Example:
    >>> pg_list_agents()
    >>> pg_list_agents(category="Research")', 'python_function', 'custom', '{"function_name": "pg_list_agents", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_agents(category: str | None = None) -> str:\n    \"\"\"\n    List all DeepAgent templates from the database with name, category, and config summary.\n\n    Use this to browse available agent configurations before selecting one.\n\n    Args:\n        category: Optional category filter (e.g. ''Research'', ''Coding'', ''Custom'')\n\n    Returns:\n        Formatted list of agents with id, name, category, model, and tool count\n\n    Example:\n        >>> pg_list_agents()\n        >>> pg_list_agents(category=\"Research\")\n    \"\"\"\n    from models.deep_agent import DeepAgentTemplate\n    db = _get_pg_session()\n    try:\n        query = db.query(DeepAgentTemplate).order_by(DeepAgentTemplate.updated_at.desc())\n        if category:\n            query = query.filter(DeepAgentTemplate.category == category)\n        agents = query.all()\n        if not agents:\n            return \"No agents found.\" if not category else f\"No agents found in category ''{category}''.\"\n        lines = [f\"## DeepAgent Templates ({len(agents)} total)\", \"\"]\n        for a in agents:\n            cfg = a.config or {}\n            tools = cfg.get(\"native_tools\", [])\n            skills = cfg.get(\"skills\", [])\n            model = cfg.get(\"model\", \"not set\")\n            lines.append(\n                f\"- **{a.name}** (id={a.id})  \"\n                f\"`{a.category}`  model=`{model}`  \"\n                f\"tools={len(tools)}  skills={len(skills)}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing agents: {e}\"\n    finally:\n        db.close()", "args_schema": {"category": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"category": {"type": "string", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "database", "order": 32, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034602+00:00', '2026-10-13 09:07:27.335167+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_agents');

