SELECT 'pg_list_projects', 'PG - List Projects', 'List all projects with their IDs, names, document count, and indexing status.

Projects group documents and workflows together.

Returns:
    Formatted list of projects

Example:
    >>> pg_list_projects()', 'python_function', 'custom', '{"function_name": "pg_list_projects", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_projects() -> str:\n    \"\"\"\n    List all projects with their IDs, names, document count, and indexing status.\n\n    Projects group documents and workflows together.\n\n    Returns:\n        Formatted list of projects\n\n    Example:\n        >>> pg_list_projects()\n    \"\"\"\n    from models.core import Project, ContextDocument\n    from sqlalchemy import func\n    db = _get_pg_session()\n    try:\n        projects = db.query(\n            Project,\n            func.count(ContextDocument.id).label(\"doc_count\")\n        ).outerjoin(\n            ContextDocument, ContextDocument.project_id == Project.id\n        ).group_by(Project.id).order_by(Project.updated_at.desc()).all()\n        if not projects:\n            return \"No projects found.\"\n        lines = [\"## Projects\", \"\"]\n        for proj, doc_count in projects:\n            lines.append(\n                f\"- **{proj.name}** (id={proj.id})  \"\n                f\"status=`{proj.status.value}`  \"\n                f\"docs={doc_count}  \"\n                f\"index={proj.indexing_status.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing projects: {e}\"\n    finally:\n        db.close()", "args_schema": {}}', '{"type": "object", "properties": {}, "required": []}', 'string', NULL, '{"category": "database", "order": 36, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034608+00:00', '2026-10-13 09:07:27.335170+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_projects');

