SELECT 'pg_list_skills', 'PG - List Skills', 'List all skills in the database with their IDs, descriptions, tags, and usage counts.

Skills define reusable capabilities that agents can auto-discover and invoke.

Returns:
    Formatted list of available skills

Example:
    >>> pg_list_skills()', 'python_function', 'custom', '{"function_name": "pg_list_skills", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_skills() -> str:\n    \"\"\"\n    List all skills in the database with their IDs, descriptions, tags, and usage counts.\n\n    Skills define reusable capabilities that agents can auto-discover and invoke.\n\n    Returns:\n        Formatted list of available skills\n\n    Example:\n        >>> pg_list_skills()\n    \"\"\"\n    from models.skill import Skill\n    db = _get_pg_session()\n    try:\n        skills = db.query(Skill).order_by(Skill.usage_count.desc()).all()\n        if not skills:\n            return \"No skills found in the database.\"\n        lines = [f\"## Skills ({len(skills)} total)\", \"\"]\n        for s in skills:\n            tags = \", \".join(s.tags or []) if s.tags else \"\"\n            tag_str = f\"  tags=[{tags}]\" if tags else \"\"\n            lines.append(\n                f\"- **{s.name}** (`{s.skill_id}`){tag_str}\\n\"\n                f\"  {s.description[:120]}{''…'' if len(s.description) > 120 else ''''}\\n\"\n                f\"  used {s.usage_count}x | source={s.source_type.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing skills: {e}\"\n    finally:\n        db.close()", "args_schema": {}}', '{"type": "object", "properties": {}, "required": []}', 'string', NULL, '{"category": "database", "order": 34, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034606+00:00', '2026-10-13 09:07:27.335169+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_skills');

