SELECT 'skill', 'Read Skill', 'Fetch a skill''s full instructions by its id.

Use when the user asks about a topic that a skill covers but the skill was
not pre-injected into your context. Reads the skill from the library on
demand (progressive disclosure).

Args:
    skill_id: The skill''s id (e.g. "web-search", "text-summarizer")', 'python_function', 'custom', '{"function_name": "skill", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nasync def skill(skill_id: str) -> str:\n    \"\"\"Fetch a skill''s full instructions by its id.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        parts = [\n            f\"# Skill: {found.name}\",\n            f\"**Description:** {found.description}\",\n            \"\",\n            found.instructions,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"", "args_schema": {"skill_id": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 24, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-15 08:09:02.162849+00:00', '2026-10-13 09:07:27.335187+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'skill');

