SELECT 'tavily_search', 'Tavily Search', 'Search the web using Tavily - an AI-optimized search engine.

Returns structured, summarized results perfect for AI consumption.
Requires TAVILY_API_KEY configured in Settings > API Keys.

Use this for more accurate, context-aware search results compared
to general web search. Especially good for research questions.

Args:
    query: The search query
    max_results: Maximum number of results to return (default: 5)

Returns:
    Search results as formatted text

Example:
    >>> await tavily_search("LangGraph v1.0 middleware system")
    >>> await tavily_search("Python async patterns", max_results=3)', 'python_function', 'custom', '{"function_name": "tavily_search", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\n# --- tavily guard ---\n\ntry:\n    from langchain_community.tools.tavily_search import TavilySearchResults\n    TAVILY_AVAILABLE = True\nexcept ImportError:\n    TAVILY_AVAILABLE = False\n\nasync def tavily_search(query: str, max_results: int = 5) -> str:\n    \"\"\"\n    Search the web using Tavily - an AI-optimized search engine.\n\n    Returns structured, summarized results perfect for AI consumption.\n    Requires TAVILY_API_KEY configured in Settings > API Keys.\n\n    Use this for more accurate, context-aware search results compared\n    to general web search. Especially good for research questions.\n\n    Args:\n        query: The search query\n        max_results: Maximum number of results to return (default: 5)\n\n    Returns:\n        Search results as formatted text\n\n    Example:\n        >>> await tavily_search(\"LangGraph v1.0 middleware system\")\n        >>> await tavily_search(\"Python async patterns\", max_results=3)\n    \"\"\"\n    try:\n        from config import get_api_key_from_db\n\n        api_key = get_api_key_from_db(\"tavily_api_key\")\n        if not api_key:\n            return (\n                \"Tavily API key not configured.\\n\\n\"\n                \"To use Tavily search:\\n\"\n                \"1. Go to Settings > API Keys\\n\"\n                \"2. Add your TAVILY_API_KEY\\n\"\n                \"3. Alternatively, use web_search (DuckDuckGo, free, no key required)\"\n            )\n\n        if not TAVILY_AVAILABLE:\n            # langchain_community is always present in LangConfig; the flag\n            # guards environments where it is missing. We call Tavily''s REST\n            # API directly below (no wrapper dependency), so this is only a\n            # soft guard.\n            pass\n\n        logger.info(f\"Tavily search: {query}\")\n\n        # Call the Tavily REST API directly — the langchain wrapper''s\n        # parameter names keep changing across versions (api_key vs\n        # tavily_api_key) and it wants an env var in some versions. Direct\n        # HTTP is stable and returns the same structured content.\n        import httpx as _httpx\n\n        async with _httpx.AsyncClient(timeout=15) as client:\n            r = await client.post(\n                \"https://api.tavily.com/search\",\n                json={\n                    \"api_key\": api_key,\n                    \"query\": query,\n                    \"max_results\": max_results,\n                    \"include_answer\": False,\n                },\n            )\n            r.raise_for_status()\n            data = r.json()\n\n        results = data.get(\"results\") or []\n        if not results:\n            return f\"No results found for: {query}\"\n\n        result_text = f\"Search results for ''{query}'' (via Tavily):\\n\\n\"\n        for i, r_item in enumerate(results, 1):\n            content = r_item.get(\"content\", \"\")\n            url = r_item.get(\"url\", \"\")\n            if url:\n                result_text += f\"{i}. {content}\\n   Source: {url}\\n\\n\"\n            else:\n                result_text += f\"{i}. {content}\\n\\n\"\n\n        logger.info(f\"Tavily search returned {len(results)} results for: {query}\")\n        return result_text\n\n    except Exception as e:\n        logger.error(f\"Tavily search failed: {e}\")\n        return f\"Tavily search error: {str(e)}\"", "args_schema": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}}', '{"type": "object", "properties": {"query": {"type": "string", "description": ""}, "max_results": {"type": "integer", "description": "", "default": 5}}, "required": ["query"]}', 'string', NULL, '{"category": "web", "order": 1, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {"requires_api_key": "TAVILY_API_KEY"}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'web', TRUE, 'TAVILY_API_KEY', '["builtin", "web"]', '2026-08-01 14:44:18.034560+00:00', '2026-08-22 15:18:58.895640+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'tavily_search');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'update_agent_prompt', 'Update Agent Prompt', 'Update the system prompt of an existing DeepAgent by id (find ids with pg_list_agents). Follows LangChain agent specs.', 'python_function', 'custom', '{"function_name": "update_agent_prompt", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\n\ndef update_agent_prompt(agent_id: int, system_prompt: str) -> str:\n    \"\"\"Update the system prompt of an existing DeepAgent (find ids with pg_list_agents).\n\n    Args:\n        agent_id: Numeric agent id (from pg_list_agents)\n        system_prompt: The new COMPLETE system prompt following LangChain agent specs\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import DeepAgentTemplate\n\n    db = SessionLocal()\n    try:\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\n        if not agent:\n            return f\"\\u274c Agent with id={agent_id} not found. Use pg_list_agents to find valid IDs.\"\n        cfg = dict(agent.config or {})\n        cfg[\"system_prompt\"] = system_prompt.strip()\n        agent.config = cfg\n        agent.lock_version = (agent.lock_version or 0) + 1  # bump optimistic-lock\n        db.commit()\n        return f\"\\u2705 Agent ''{agent.name}'' (id={agent.id}) system prompt updated.\"\n    except Exception as e:\n        db.rollback()\n        return f\"\\u274c Failed to update prompt: {e}\"\n    finally:\n        db.close()\n", "args_schema": {"agent_id": {"type": "integer", "description": "Numeric agent id (from pg_list_agents)"}, "system_prompt": {"type": "string", "description": "The new COMPLETE system prompt"}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": "Numeric agent id (from pg_list_agents)"}, "system_prompt": {"type": "string", "description": "The new COMPLETE system prompt"}}, "required": ["agent_id", "system_prompt"]}', 'string', NULL, '{"category": "custom"}', TRUE, FALSE, NULL, FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', FALSE, NULL, '[]', '2026-08-04 08:00:53.466517+00:00', '2026-08-04 08:00:53.466524+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'update_agent_prompt');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'update_skill', 'Update Skill', 'Update an existing skill in the database. Only provided fields are updated.

Args:
    skill_id: The kebab-case ID of the skill to update
    name: New human-readable name
    description: New description
    instructions: New instructions
    tags: New list of tags
    triggers: New list of triggers', 'python_function', 'custom', '{"function_name": "update_skill", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport re as _re\n\nasync def skill(skill_id: str) -> str:\n    \"\"\"Fetch a skill''s full instructions by its id.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        parts = [\n            f\"# Skill: {found.name}\",\n            f\"**Description:** {found.description}\",\n            \"\",\n            found.instructions,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"\n\ndef update_skill(skill_id: str, name: str | None = None,\n                 description: str | None = None,\n                 instructions: str | None = None,\n                 tags: list[str] | None = None,\n                 triggers: list[str] | None = None) -> str:\n    \"\"\"Update an existing skill in the database. Only provided fields are updated.\n\n    Args:\n        skill_id: The kebab-case ID of the skill to update\n        name: New human-readable name\n        description: New description\n        instructions: New instructions\n        tags: New list of tags\n        triggers: New list of triggers\n    \"\"\"\n    from db.database import SessionLocal\n    from models.skill import Skill\n    import datetime\n    import re as _re\n\n    # Sanitize the identifier — only kebab-case ids are valid; anything else is\n    # rejected before touching the DB (defense-in-depth against odd inputs).\n    if not _re.fullmatch(r\"[a-z0-9][a-z0-9-]*\", skill_id or \"\"):\n        return f\"❌ Invalid skill_id ''{skill_id}'': use kebab-case (letters, digits, hyphens).\"\n\n    db = SessionLocal()\n    try:\n        skill = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n        if not skill:\n            return f\"❌ Skill ''{skill_id}'' not found. Use create_skill first.\"\n\n        if name is not None:\n            skill.name = name.strip()\n        if description is not None:\n            skill.description = description.strip()\n        if instructions is not None:\n            skill.instructions = instructions.strip()\n        if tags is not None:\n            skill.tags = tags\n        if triggers is not None:\n            skill.triggers = triggers\n        skill.updated_at = datetime.datetime.now(datetime.timezone.utc)\n        db.commit()\n        return f\"✅ Skill ''{skill_id}'' updated successfully!\"\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to update skill: {e}\"\n    finally:\n        db.close()", "args_schema": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "string", "description": "", "default": null}, "triggers": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "string", "description": "", "default": null}, "triggers": {"type": "string", "description": "", "default": null}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 25, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-01 14:44:18.034635+00:00', '2026-10-13 09:07:27.335180+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'update_skill');

